   if den>1e-9:
    grad=((xs-mean)[:,None]*(coords-coords.mean(axis=0))).sum(axis=0)/den
    for li in p.loop_indices:
     dx=oldx[o.data.loops[li].vertex_index]*(factor-1);uv.data[li].uv+=Vector(grad*dx)
  for v in o.data.vertices:v.co.x*=factor
