  X=Vector((0,1,slope)).normalized();Y=Vector((-1,0,0));Z=X.cross(Y).normalized();rot=Matrix((X,Y,Z)).transposed().to_4x4();rot.translation=center;o.matrix_world=rot;o.data.update()
