 a=math.radians(-81.5);wx=12.35+math.cos(a)*x-math.sin(a)*y;wz=34-math.sin(a)*x-math.cos(a)*y
 shore=8+2*math.sin(wz*.14)+.6*math.sin(wz*.37+.4)+2.2*math.exp(-((wz+2.5)/3.6)**2)-.85*math.exp(-((wz-2.5)/2.34)**2);off=wx-shore
 if off<0:d=-off;z=-.11*d-.013*d*d/(1+d*.025)
